{
  "name": "opencode-subagents-view",
  "version": "0.3.0",
  "description": "Terminal UI plugin for OpenCode that adds a live \"Subagents\" panel to the session sidebar. Unofficial, not affiliated with the OpenCode team.",
  "type": "module",
  "license": "MIT",
  "author": "Giovanni Calà",
  "homepage": "https://github.com/giovannic96/opencode-subagents-view#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/giovannic96/opencode-subagents-view.git"
  },
  "bugs": {
    "url": "https://github.com/giovannic96/opencode-subagents-view/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui"
  ],
  "engines": {
    "opencode": ">=1.17.0"
  },
  "exports": {
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src"
  ],
  "scripts": {
    "test": "bun test --conditions=browser",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opentui/solid": "^0.4.3",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.17.11",
    "@opentui/core": "^0.4.3",
    "@types/bun": "^1.3.14",
    "typescript": "^6.0.3"
  }
}
